#!/usr/bin/env node
'use strict';
const { execSync } = require('node:child_process');
const { existsSync } = require('node:fs');
const { join } = require('node:path');

const DATA_PACKAGE = '@example/region-data';
const cwd = process.cwd();

if (existsSync(join(cwd, 'yarn.lock'))) {
  execSync('yarn upgrade @example/region-data', { cwd, stdio: 'inherit' });
} else {
  execSync('npm update @example/region-data', { cwd, stdio: 'inherit' });
}
console.log(`Updated ${DATA_PACKAGE} in the lockfile.`);

